// Regression fixture for #59 — laundering past the ESM resolve hook.
//
// None of these specifiers NAMES a mediated builtin, so a resolve hook that classifies on the
// specifier string alone lets them through to the raw builtin. They all resolve to one, which
// is why capwall must classify on the URL Node resolves to. Kept deliberately inert per
// AGENTS.md § 8: it reads only its own data.txt and spawns `node -e ""`, which does nothing.
import { fileURLToPath } from "node:url";

const DATA = fileURLToPath(new URL("./data.txt", import.meta.url));

/** `BLOCKED:<pkg>` when capwall mediated the module, `ERR:<code>` for anything else. */
function outcome(err) {
  return err && err.name === "CapabilityError" ? `BLOCKED:${err.pkg}` : `ERR:${err && err.code}`;
}

/** Returns one `"<route>:<OUTCOME>"` line per laundering route, for the app to print. */
export async function launder() {
  const out = [];

  // A `data:` URL module is its own resolution context with no filesystem parent, and its
  // re-export is the specifier that actually reaches the builtin. `import.meta.resolve` is the
  // other shape: resolve the private specifier to a URL by hand, then import THAT string — which
  // is a `node:` URL, so it lands on capwall's fast path rather than its resolved-URL check.
  const DATA_URL_REEXPORT =
    "data:text/javascript," + encodeURIComponent(`export * from ${JSON.stringify("node:fs")};`);

  for (const [route, spec] of [
    ["bare-fs", "#bare-fs"],
    ["cond-fs", "#cond-fs"],
    ["pat-fs", "#pat/fs"],
    // A module reached through this package's own `exports` map, by package NAME (self-reference),
    // which then re-exports `#bare-fs`.
    ["self-fs", "esm-launder-dep/reexport"],
    ["data-fs", DATA_URL_REEXPORT],
    ["meta-fs", import.meta.resolve("#bare-fs")],
  ]) {
    try {
      const fs = await import(spec);
      out.push(`${route}:RAW:${fs.readFileSync(DATA, "utf8").trim()}`);
    } catch (err) {
      out.push(`${route}:${outcome(err)}`);
    }
  }

  // `fs/promises` is a SEPARATE mediated specifier with its own shim surface, and a rejected
  // promise rather than a synchronous throw — its own laundering route, not a variant of `fs`.
  try {
    const fsp = await import("#bare-fsp");
    out.push(`bare-fsp:RAW:${(await fsp.readFile(DATA, "utf8")).trim()}`);
  } catch (err) {
    out.push(`bare-fsp:${outcome(err)}`);
  }

  try {
    const cp = await import("#bare-cp");
    cp.execSync(`${process.execPath} -e ""`);
    out.push("bare-cp:RAW");
  } catch (err) {
    out.push(`bare-cp:${outcome(err)}`);
  }

  return out;
}
